    let query = supabase.from("generated_slots").select("id, date_time_start, date_time_end, max_capacity, confirmed_bookings, service_id, professional_id").eq("is_active", true).gte("date_time_start", `${date_from}T00:00:00`).lte("date_time_start", `${date_to}T23:59:59`).order("date_time_start", { ascending: true }).limit(500);
